498	/* --- 音符レイヤー（スクロールに合わせて弧を描いて流れる装飾） --- */
499	.pn-notes { position: fixed; top: 0; bottom: 0; left: 50%; transform: translateX(-50%); width: min(100%,375px); z-index: 1; pointer-events: none; overflow: hidden; }
500	.pn-wave { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
501	.pn-wave__ghost { fill: none; stroke: rgba(201,163,78,0.15); stroke-width: 1; }
502	.pn-wave__live { fill: none; stroke: url(#pnWaveGrad); stroke-width: 1.4; stroke-linecap: round; }
503	.pn-note { position: absolute; left: 0; top: 0; font-family: "Cormorant Garamond", Georgia, serif; line-height: 1; color: rgba(201,163,78,0.55); will-change: transform; }
504	.pn-note__glyph { display: block; transform-origin: 50% 50%; animation: pnDrift var(--pn-dur,7s) ease-in-out infinite; }
505	.pn-note--lead { font-size: 26px; color: #C9A34E; --pn-dur: 6.5s; }
506	.pn-note--trail-a { font-size: 16px; color: rgba(201,163,78,0.5); --pn-dur: 8.5s; }
507	.pn-note--trail-b { font-size: 12px; color: rgba(201,163,78,0.3); --pn-dur: 10s; }
508	@keyframes pnDrift { 0%,100% { transform: translateY(0) rotate(0deg); } 50% { transform: translateY(-6px) rotate(-5deg); } }
509	@media (prefers-reduced-motion: reduce) { .pn-note__glyph { animation: none; } }
